def extract_json(text: str) -> dict:
    text = text.strip()
    text = re.sub(r"^```(?:json)?", "", text).strip()
    text = re.sub(r"```$", "", text).strip()
    start = text.find("{")
    end = text.rfind("}")
    if start == -1 or end == -1:
        raise ValueError("Javobda JSON topilmadi")
    return json.loads(text[start:end + 1])


REQUIRED_FIELDS = [
    "official_name", "capital", "language", "population", "area", "government",
    "description", "geography", "currency", "presidents_count", "presidents",
    "military", "symbols", "events",
]


def _fetch_or_generate_country(name: str) -> dict:
    """Returns full country data dict (without name/cached keys), using cache when available."""
    with get_db() as conn:
        row = conn.execute(
            "SELECT data_json FROM country_info WHERE name = ?", (name,)
        ).fetchone()
        if row:
            return json.loads(row["data_json"])

    if not groq_client:
        raise HTTPException(500, "GROQ_API_KEY sozlanmagan")

    try:
        completion = groq_client.chat.completions.create(
            model=GROQ_MODEL,
            messages=[
                {"role": "system", "content": SYSTEM_PROMPT},
                {"role": "user", "content": f"Davlat: {name}"},
            ],
            temperature=0.5,
            max_tokens=3200,
            response_format={"type": "json_object"},
        )
        raw = completion.choices[0].message.content
        parsed = extract_json(raw)
        list_fields = {"events", "presidents"}
        dict_fields = {"currency", "military"}
        for field in REQUIRED_FIELDS:
            if field not in parsed:
                if field in list_fields:
                    parsed[field] = []
                elif field in dict_fields:
                    parsed[field] = {}
                else:
                    parsed[field] = ""
    except Exception as e:
        raise HTTPException(502, f"AI javobini olishda xatolik: {e}")

    with get_db() as conn:
        conn.execute(
            "INSERT OR REPLACE INTO country_info (name, data_json) VALUES (?, ?)",
            (name, json.dumps(parsed, ensure_ascii=False)),
        )
    return parsed


VERDICT_SYSTEM_PROMPT = (
    "Siz harbiy va geosiyosiy tahlilchisiz. Sizga ikkita davlat haqida qisqacha "
    "statistik ma'lumot (aholi, harbiy xizmatchilar, tanklar, harbiy samolyotlar, "
    "dengiz floti, iqtisodiy holat) beriladi. Faraziy, sof statistikaga asoslangan "
    "harbiy to'qnashuvda qaysi davlat ustunlikka ega bo'lishi mumkinligi haqida "
    "o'ynoqi, lekin bilimga asoslangan taxmin bering. Bu jiddiy prognoz emas, "
    "shunchaki qiziqarli statistik taqqoslash ekanini yodda tuting. Javobingiz "
    "FAQAT quyidagi JSON formatida bo'lishi kerak, boshqa hech narsa qo'shmang:\n"
    '{"winner": "ustunlikka ega davlat nomi (yoki \'Aniq emas\' agar juda teng bo\'lsa)", '
    '"reasoning": "2-3 jumlali qisqacha, aniq raqamlarga asoslangan izoh"}'
)


def _load_country_by_name(name: str) -> dict:
    data = _fetch_or_generate_country(name)
    d = dict(data)
    d["name"] = name
    return d


@app.get("/api/compare-verdict")
def get_compare_verdict(a: str, b: str):
    a, b = a.strip(), b.strip()
    if not a or not b:
        raise HTTPException(400, "Ikkala davlat nomi ham berilishi kerak")

    pair_key = "|".join(sorted([a.lower(), b.lower()]))

    with get_db() as conn:
        row = conn.execute(
            "SELECT data_json FROM compare_verdict WHERE pair_key = ?", (pair_key,)
        ).fetchone()
        if row:
            return json.loads(row["data_json"])

    if not groq_client:
        raise HTTPException(500, "GROQ_API_KEY sozlanmagan")

    country_a = _load_country_by_name(a)
    country_b = _load_country_by_name(b)

    def summarize(c):
        mil = c.get("military", {}) or {}
        return (
            f"{c['name']}: aholi={c.get('population', '?')}, "
            f"harbiy xizmatchilar={mil.get('personnel', '?')}, "
            f"tanklar={mil.get('tanks', '?')}, "
            f"harbiy samolyotlar={mil.get('aircraft', '?')}, "
            f"dengiz floti={mil.get('navy', '?')}"
        )

    prompt = f"1-davlat — {summarize(country_a)}\n2-davlat — {summarize(country_b)}"

    try:
        completion = groq_client.chat.completions.create(
            model=GROQ_MODEL,
            messages=[
                {"role": "system", "content": VERDICT_SYSTEM_PROMPT},
                {"role": "user", "content": prompt},
            ],
            temperature=0.6,
            max_tokens=400,
            response_format={"type": "json_object"},
        )
        raw = completion.choices[0].message.content
        verdict = extract_json(raw)
        verdict.setdefault("winner", "Aniq emas")
        verdict.setdefault("reasoning", "")
    except Exception as e:
        raise HTTPException(502, f"AI javobini olishda xatolik: {e}")

    with get_db() as conn:
        conn.execute(
            "INSERT OR REPLACE INTO compare_verdict (pair_key, data_json) VALUES (?, ?)",
            (pair_key, json.dumps(verdict, ensure_ascii=False)),
        )

    return verdict
@app.get("/api/country/{name}")
def get_country_info(name: str):
    name = name.strip()
    if not name:
        raise HTTPException(400, "Davlat nomi bo'sh bo'lishi mumkin emas")

    with get_db() as conn:
        cached = conn.execute(
            "SELECT 1 FROM country_info WHERE name = ?", (name,)
        ).fetchone() is not None

    parsed = _fetch_or_generate_country(name)
    parsed = dict(parsed)
    parsed["name"] = name
    parsed["cached"] = cached
    return parsed


# ---------------------------------------------------------------------------
# Frontend (single-file bundle): the whole globe UI (HTML/CSS/JS) is embedded
# below as base64, so the entire backend + frontend ships as ONE Python file.
# ---------------------------------------------------------------------------
_INDEX_HTML_B64 = ""
INDEX_HTML = base64.b64decode(_INDEX_HTML_B64).decode("utf-8")


@app.get("/", response_class=HTMLResponse)
def serve_index():
    return HTMLResponse(content=INDEX_HTML)
